CREATE TABLE IF NOT EXISTS olts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,vendor TEXT NOT NULL DEFAULT 'HSGQ',model TEXT NOT NULL DEFAULT 'HSGQ-G04R',host TEXT,management_protocol TEXT NOT NULL DEFAULT 'inventory_only',management_port INTEGER,location TEXT,firmware_version TEXT,status TEXT NOT NULL DEFAULT 'unknown',credential_username TEXT,credential_password TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS olt_pon_ports(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,olt_id TEXT NOT NULL REFERENCES olts(id) ON DELETE CASCADE,port_index INTEGER NOT NULL CHECK(port_index BETWEEN 1 AND 4),label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unknown',notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,olt_id,port_index),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS onus(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,olt_id TEXT NOT NULL REFERENCES olts(id) ON DELETE CASCADE,pon_port_id TEXT NOT NULL,serial_number TEXT NOT NULL,model TEXT,customer_id TEXT,status TEXT NOT NULL DEFAULT 'unknown',rx_power_dbm REAL,tx_power_dbm REAL,last_seen_at TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,serial_number),FOREIGN KEY(tenant_id,pon_port_id) REFERENCES olt_pon_ports(tenant_id,id),FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS onu_service_mappings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,onu_id TEXT NOT NULL REFERENCES onus(id) ON DELETE CASCADE,customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,subscription_id TEXT REFERENCES subscriptions(id) ON DELETE SET NULL,service_label TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,onu_id));
CREATE TABLE IF NOT EXISTS onu_connection_history(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,onu_id TEXT NOT NULL REFERENCES onus(id) ON DELETE CASCADE,event_type TEXT NOT NULL,old_status TEXT,new_status TEXT,details TEXT,occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS olt_alarms(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,olt_id TEXT NOT NULL REFERENCES olts(id) ON DELETE CASCADE,pon_port_id TEXT,onu_id TEXT,severity TEXT NOT NULL DEFAULT 'warning',alarm_code TEXT,message TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'manual',status TEXT NOT NULL DEFAULT 'open',occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,cleared_at TEXT,FOREIGN KEY(tenant_id,pon_port_id) REFERENCES olt_pon_ports(tenant_id,id),FOREIGN KEY(onu_id) REFERENCES onus(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_olts_tenant ON olts(tenant_id);CREATE INDEX IF NOT EXISTS idx_pon_olt ON olt_pon_ports(tenant_id,olt_id);CREATE INDEX IF NOT EXISTS idx_onu_olt_pon ON onus(tenant_id,olt_id,pon_port_id);CREATE INDEX IF NOT EXISTS idx_onu_history ON onu_connection_history(tenant_id,onu_id,occurred_at);CREATE INDEX IF NOT EXISTS idx_olt_alarms ON olt_alarms(tenant_id,olt_id,status,occurred_at);